// Reads the inbound email and every attachment -- any binary property, regardless of
// naming, so this doesn't depend on a specific attachment-prefix setting.
const item = $input.first();
const json = item.json;

// Defensive extraction -- IMAP parser output shape can vary; try the structured form first,
// fall back to pulling an email address out of a raw string.
const fromField = json.from;
let senderRaw = '';
if (fromField && fromField.value && fromField.value[0] && fromField.value[0].address) {
  senderRaw = fromField.value[0].address;
} else if (typeof fromField === 'string') {
  senderRaw = fromField;
} else if (fromField && fromField.text) {
  senderRaw = fromField.text;
}
const emailMatch = senderRaw.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
const sender_email = (emailMatch ? emailMatch[0] : senderRaw).trim().toLowerCase();

const subject     = String(json.subject || '').trim();
const received_at = json.date || new Date().toISOString();

const attachmentKeys = Object.keys(item.binary || {});

return [{
  json: {
    sender_email,
    subject,
    received_at,
    attachment_count: attachmentKeys.length,
    attachment_keys: attachmentKeys,
    has_attachments: attachmentKeys.length > 0,
  },
  binary: item.binary,
}];

// Filters Clio's (broad, fuzzy) contact search down to an exact email match. A
// partial/fuzzy match here risks filing a document under the wrong client's matter, which
// is far worse than routing to manual filing -- so this stays strict.
const meta = $('Extract Email Metadata').item.json;
const response = $input.first().json;
const contacts = response.data || [];

const match = contacts.find(c => String(c.primary_email_address || '').trim().toLowerCase() === meta.sender_email);

return [{ json: {
  ...meta,
  contact_id: match ? match.id : null,
  contact_name: match ? match.name : null,
  is_contact_found: !!match,
} }];

// Decides which matter this document belongs to -- metadata and rules only, never content.
const meta = $('Extract Contact Match').item.json;
const response = $input.first().json;
const matters = response.data || [];

let matched = null;
if (matters.length === 1) {
  // Only one open matter for this client -- confident match.
  matched = matters[0];
} else if (matters.length > 1) {
  // More than one open matter for this client -- only proceed if the matter's own
  // display_number appears verbatim in the subject line. This is a reference-number
  // check, not reading what the document says -- still metadata/rules, not content.
  const subjectLower = meta.subject.toLowerCase();
  matched = matters.find(m => m.display_number && subjectLower.includes(String(m.display_number).toLowerCase())) || null;
}

return [{ json: {
  ...meta,
  matter_id: matched ? matched.id : null,
  matter_display_number: matched ? matched.display_number : null,
  matter_description: matched ? matched.description : null,
  open_matter_count: matters.length,
  is_matter_found: !!matched,
} }];

// Reads whether a matching Drive folder was found. Explicit node references throughout
// this workflow (rather than $json) because every Drive/Clio API call replaces the item's
// data with its own response.
const meta = $('Determine Matching Matter').item.json;
const results = $input.all();
const found = results.length > 0 ? results[0].json : null;

return [{ json: {
  ...meta,
  existing_folder_id: found ? found.id : null,
  folder_exists: !!found,
} }];

// Fans out into one item per attachment -- everything downstream uploads one file at a
// time. Converges both the 'folder already existed' and 'folder just created' branches:
// reads matter/email metadata from 'Determine Matching Matter' explicitly either way, and
// resolves folder_id from whichever branch actually ran.
const meta = $('Determine Matching Matter').item.json;
const input = $input.first().json;

// If this ran right after Create Matter Folder, input.id is the new folder's id.
// If it ran right after the 'exists' branch (which passes through unchanged from Check If
// Matter Folder Exists), input.existing_folder_id is already set.
const folder_id = input.id || input.existing_folder_id;

const attachmentKeys = $('Extract Email Metadata').item.json.attachment_keys;
const receivedDate = new Date(meta.received_at).toISOString().slice(0, 10);

return attachmentKeys.map(key => ({
  json: {
    matter_id: meta.matter_id,
    matter_display_number: meta.matter_display_number,
    sender_email: meta.sender_email,
    subject: meta.subject,
    folder_id,
    binary_key: key,
    received_date: receivedDate,
  },
  binary: { data: $('Extract Email Metadata').item.binary[key] },
}));

// Runs once after all attachments for this email have been filed, to build one compliance
// log entry and one internal summary rather than one per attachment.
const items = $input.all();
const first = items[0].json;

return [{ json: {
  matter_display_number: first.matter_display_number,
  sender_email: first.sender_email,
  subject: first.subject,
  filed_count: items.length,
} }];

// Builds the staff alert for an email that couldn't be confidently matched to a matter --
// pulls the ORIGINAL attachments straight from the trigger node by name, since every Clio
// API call in between replaced the item's binary data with its own response.
const meta = $input.first().json;
const triggerItem = $('Extract Email Metadata').item;
const attachmentKeys = triggerItem.json.attachment_keys;

const reason = meta.is_contact_found === false
  ? 'No Clio contact matches this sender\'s email address.'
  : (meta.open_matter_count === 0
      ? 'This contact has no open matters.'
      : `This contact has ${meta.open_matter_count} open matters and none match a reference number in the subject line.`);

const binary = {};
attachmentKeys.forEach((key, i) => {
  binary[`file${i}`] = triggerItem.binary[key];
});

return [{
  json: {
    sender_email: meta.sender_email,
    subject: meta.subject,
    reason,
    attachment_count: attachmentKeys.length,
  },
  binary,
}];
